import sys


def main():
    data = sys.stdin.read().split()
    if not data:
        print(-1)
        return
    rows = data
    h = len(rows)
    w = max(len(r) for r in rows)
    grid = bytearray(h * w)
    s = e = -1
    for y, r in enumerate(rows):
        base = y * w
        for x, ch in enumerate(r):
            if ch == '#':
                continue
            grid[base + x] = 1
            if ch == 'S':
                s = base + x
            elif ch == 'E':
                e = base + x
    if s < 0 or e < 0:
        print(-1)
        return
    if s == e:
        print(0)
        return
    dist = [-1] * (h * w)
    dist[s] = 0
    frontier = [s]
    d = 0
    while frontier:
        d += 1
        nxt = []
        for p in frontier:
            x = p % w
            cands = []
            if x > 0:
                cands.append(p - 1)
            if x < w - 1:
                cands.append(p + 1)
            if p >= w:
                cands.append(p - w)
            if p + w < h * w:
                cands.append(p + w)
            for q in cands:
                if grid[q] and dist[q] < 0:
                    if q == e:
                        print(d)
                        return
                    dist[q] = d
                    nxt.append(q)
        frontier = nxt
    print(-1)


main()
